insert into public.files (id, owner_id, space_kind, space_ref, uploader_id, kind, storage_path, mime, size_bytes, status, chunk_total, chunk_done, created_at, updated_at) values ('da7f46b9-f835-531f-bcb3-c8e8497a7c92', '286d1368-7a94-55df-8b5a-914bca9a906e', 'personal', '286d1368-7a94-55df-8b5a-914bca9a906e', '286d1368-7a94-55df-8b5a-914bca9a906e', 'user_upload', '286d1368-7a94-55df-8b5a-914bca9a906e/da7f46b9-f835-531f-bcb3-c8e8497a7c92/미분_공식_정리.txt', 'text/plain', 2289, 'indexed', 4, 4, now() - interval '25740 minutes', now() - interval '25739 minutes');
insert into public.file_chunks (id, file_id, seq, chunk_text, embedding, status, created_at) values ('afbc5f89-2a0b-5b9a-86aa-da386cd60630', 'da7f46b9-f835-531f-bcb3-c8e8497a7c92', 0, '# 미분 공식 정리 노트
## 1. 미분계수와 도함수
함수 f(x)의 x = a에서의 미분계수는 평균변화율의 극한으로 정의한다.
f''(a) = lim(h→0) [f(a+h) − f(a)] / h
이 값은 곡선 y = f(x) 위의 점 (a, f(a))에서 그은 접선의 기울기와 같다.
모든 x에 대해 미분계수를 대응시킨 함수 f''(x)를 도함수라고 하고, 도함수를 구하는 과정을 미분한다고 말한다.
미분가능한 함수는 반드시 연속이지만, 연속이라고 해서 항상 미분가능한 것은 아니다. 예를 들어 f(x) = |x|는 x = 0에서 연속이지만 뾰족점이 있어 미분가능하지 않다.
## 2. 기본 공식
- 상수함수: (c)'' = 0
- 거듭제곱 법칙: (xⁿ)'' = n·xⁿ⁻¹ (n은 실수)
- 상수배: (c·f)'' = c·f''
- 합과 차: (f ± g)'' = f'' ± g''
예) f(x) = 3x⁴ − 2x² + 5x − 7 이면 f''(x) = 12x³ − 4x + 5', '[-0.0280664,0.0044807,0.0307404,-0.0989646,0.0068177,0.0717771,0.0318175,-0.0244269,-0.0038956,0.0008355,0.0137716,-0.0075494,0.0019321,-0.0324761,0.1935559,-0.0233499,0.0057743,0.0162170,0.0118365,-0.0469083,0.0104647,0.0398488,-0.0433428,0.0415207,-0.0393759,0.0343478,-0.0126149,0.0410389,0.0240839,0.0160437,0.0115137,0.0302341,0.0010756,0.0007378,-0.0287349,0.0469981,0.0226232,0.0217077,-0.0090273,0.0514106,0.0010142,0.0026953,-0.0050737,-0.0314189,0.0385527,0.0118352,-0.0084731,-0.0434689,-0.0004809,0.0009581,0.0162469,0.0126891,-0.0255988,-0.3310873,0.0136743,0.0257533,-0.0508057,0.0290011,0.0225517,-0.0000636,-0.0235268,0.0663424,0.0110726,0.0177616,-0.0204464,0.0131034,0.0657271,0.0685207,-0.0690116,-0.0393631,0.0268679,0.0309455,-0.0054247,-0.0376687,-0.0380507,-0.0259057,0.0070444,0.0278143,-0.0111527,0.0260236,0.0179036,-0.0341958,0.0207202,0.0040821,0.0032828,0.0128430,-0.0409816,-0.0129659,-0.0177166,-0.0238595,0.0105814,0.0402287,0.0184999,0.0109670,-0.0078988,0.0061302,-0.0078617,0.0099550,-0.0194952,-0.0188832,0.0185331,-0.0215328,-0.0299219,-0.0025098,-0.0140090,-0.0074240,-0.0070437,-0.0055427,-0.0047360,0.0341911,0.0105384,0.0007728,0.0272208,-0.0009084,0.0267276,-0.3488288,0.0080895,-0.0133954,0.0130748,-0.0079484,0.0086221,-0.0069948,-0.0126874,-0.0022127,0.0177382,-0.0143432,-0.0291795,0.0158231,0.0309820,-0.0367589,0.0079133,-0.0061889,-0.0248243,-0.0284562,0.0170496,0.0546103,-0.0480157,0.0071593,-0.0236677,-0.0052718,-0.0371166,-0.0039093,0.0263029,0.0032277,0.0047235,-0.0199113,-0.0451950,0.0166300,-0.0016896,-0.0790810,0.0020795,-0.0288160,-0.0096186,0.0121156,0.0451564,-0.0944112,0.0213852,0.0132385,0.0154445,-0.0277379,-0.0297883,-0.0244235,-0.0231408,0.0114348,0.0086201,-0.0021839,0.0119865,0.0361772,-0.0567201,0.0189003,-0.0304471,0.0159948,0.0279517,-0.0072672,-0.0557236,-0.0105128,0.0143912,0.0153124,-0.0177633,0.0149879,0.0389392,0.0188058,0.0011039,-0.0232953,0.0110086,-0.005