insert into public.file_chunks (id, file_id, seq, chunk_text, embedding, status, created_at) values ('56f93338-080d-5038-b3af-b513d32b66f0', 'db20e43e-55a6-578d-a949-cb4f66e0ffbd', 4, '8분자)가 만들어진다. 최종 전자 수용체는 산소이다.
→ 포도당 1분자당 약 30~32분자의 ATP (교과서에 따라 36~38로 제시되기도 함)
■ 3. 산소가 없을 때: 발효
산소가 없으면 전자 전달계가 멈추므로 해당과정만으로 ATP를 얻는다.
 · 젖산 발효: 근육 세포, 유산균 → 피루브산이 젖산으로
 · 알코올 발효: 효모 → 에탄올 + CO₂
발효는 포도당 1분자당 ATP 2분자만 얻으므로 효율이 낮다.
■ 4. 광합성과 세포 호흡의 관계
광합성의 산물(포도당, O₂)은 세포 호흡의 재료가 되고, 세포 호흡의 산물(CO₂, H₂O)은 광합성의 재료가 된다. 에너지는 빛에너지 → 화학 에너지(포도당) → ATP → 생명 활동으로 흐른다.
엽록체와 미토콘드리아는 모두 자체 DNA와 리보솜, 이중막을 가지며, 원래 독립된 원핵생물이 공생하게 되었다는 세포내 공생설의 근거가 된다.', '[0.0308861,0.0325064,-0.0054001,-0.1031076,0.0457464,0.0040912,-0.0044504,0.0251676,0.0144170,0.0073754,0.0357113,0.0084837,-0.0060456,-0.0073894,0.1901117,-0.0237944,-0.0001214,-0.0341205,-0.0040811,-0.0233210,0.0278479,0.0008411,-0.0133922,-0.0232516,-0.0461443,0.0265824,0.0221755,0.0035029,0.0527687,0.0239368,0.0086484,0.0478412,-0.0035804,0.0217819,0.0063001,0.0000400,0.0309971,0.0017853,-0.0233809,0.0019420,-0.0400746,-0.0074707,0.0176684,-0.0128799,0.0169416,-0.0212621,0.0057054,0.0050536,0.0413791,0.0140902,0.0299853,0.0659382,-0.0298732,-0.3141280,-0.0264288,-0.0679577,-0.0216519,-0.0110821,-0.0074989,-0.0108956,-0.0111692,0.0436335,0.0168316,0.0087495,-0.0231213,-0.0370017,0.0017235,0.0543603,0.0149007,0.0057191,-0.0414855,0.0230967,-0.0141400,-0.0112326,-0.0094007,-0.0577592,0.0109148,0.0398616,0.0085247,0.0361034,0.0095316,-0.0894866,-0.0541035,0.0222587,0.0101147,0.0077870,-0.0252555,0.0149230,-0.0066801,0.0032768,-0.0301374,0.0005177,0.0276420,0.0088893,0.0114644,-0.0026131,-0.0393027,0.0187601,-0.0153433,-0.0140826,-0.0381307,0.0057873,0.0118125,-0.0067929,0.0015442,-0.0263019,-0.0287087,0.0513255,-0.0195547,-0.0334946,-0.0014400,0.0178094,0.0408524,0.0067093,0.0205028,-0.3140494,-0.0324861,0.0105020,-0.0203983,0.0310789,0.0101881,0.0590616,-0.0020092,0.0314101,-0.0051797,0.0064382,-0.0544869,-0.0011461,0.0263238,-0.0215490,0.0715523,0.0052332,-0.0529894,0.0229142,-0.0135376,0.0654837,-0.0140947,-0.0362688,-0.0477048,0.0205204,-0.0187269,0.0042567,0.0166208,0.0438085,-0.0219150,-0.0536525,-0.0252246,0.0078941,-0.0143969,-0.0117133,0.0007076,0.0315243,0.0071468,-0.0048779,-0.0209168,-0.0490763,-0.0068616,-0.0143051,0.0038194,-0.0204190,-0.0039809,0.0087006,-0.0126935,-0.0022818,0.0495666,-0.0081137,-0.0183667,0.0395743,-0.0039549,0.0245349,-0.0065941,0.0243193,0.0032672,-0.0185870,-0.0277386,0.0366369,0.0260778,-0.0148887,0.0428501,0.0218836,0.0033501,-0.0028243,-0.0322505