2,0.0058785,0.0411702,0.0103992,0.0302948,-0.0248663,0.0139636,0.0440417,0.0031622,0.0110742,0.0195443,-0.0109044,-0.0071426,-0.0006684,-0.0097276,-0.0168306,0.0138223,0.0056982,0.0152747,-0.0433794,0.0135189,0.0172540,-0.0290587,-0.0210994,0.0131430,-0.0031700]'::vector, 'embedded', now() - interval '22859 minutes');
insert into public.file_chunks (id, file_id, seq, chunk_text, embedding, status, created_at) values ('489619ac-ac9e-57f2-a5aa-9efffa3e2d84', '1f4190ea-f260-5c04-a135-d9189f8e97b5', 1, '1. 핵: 유전 물질(DNA)을 저장하고 세포 활동을 조절한다. 핵막에는 핵공이 있어 mRNA가 세포질로 나간다.
2. 리보솜: 단백질을 합성하는 장소. 막이 없는 작은 알갱이로, 세포질에 떠 있거나 거친면 소포체에 붙어 있다.
3. 소포체
 - 거친면 소포체: 표면에 리보솜이 붙어 있어 분비 단백질을 만들고 운반한다.
 - 매끈면 소포체: 리보솜이 없으며 지질 합성, 해독 작용을 한다.
4. 골지체: 소포체에서 온 단백질을 가공·포장하여 세포 밖으로 분비하거나 필요한 곳으로 보낸다.
5. 리소좀: 가수 분해 효소가 들어 있어 세포 내 소화를 담당한다. 주로 동물 세포에서 관찰된다.
6. 미토콘드리아: 세포 호흡으로 ATP를 생성한다. 이중막 구조이며 자체 DNA가 있다.
7. 엽록체(식물 세포): 광합성이 일어나는 장소. 틸라코이드와 스트로마로 구성된다.
8. 세포벽(식물 세포): 셀룰로스로 이루어져 세포를 보호하고 모양을 유지한다.
9. 액포: 물과 노폐물, 색소를 저장한다. 성', '[-0.0170543,0.0355123,-0.0040418,-0.0657139,0.0287107,-0.0110701,0.0093587,0.0168003,0.0208691,0.0267527,0.0406944,0.0145055,0.0178328,-0.0055645,0.1774103,-0.0517593,0.0209567,-0.0046350,-0.0115414,-0.0567376,0.0195684,-0.0100121,-0.0009713,0.0377217,-0.0634729,0.0156222,0.0362777,0.0151655,0.0364116,-0.0155335,-0.0128610,0.0301473,-0.0269270,-0.0073241,0.0086471,0.0199314,0.0101817,-0.0045626,-0.0118765,-0.0042752,-0.0049310,0.0048526,0.0170595,0.0140087,0.0130465,0.0026035,0.0314139,-0.0184013,0.0278255,-0.0024523,-0.0063136,0.0408488,-0.0026821,-0.3218364,-0.0112424,-0.0418661,-0.0198425,-0.0051297,-0.0074209,-0.0261903,-0.0186366,0.0448640,-0.0031795,0.0207540,-0.0004964,-0.0555420,0.0003141,0.0473860,-0.0250307,-0.0177121,-0.0431537,0.0143730,-0.0075003,0.0201501,-0.0443226,-0.0462684,0.0439828,0.0333937,0.0301933,0.0553639,0.0213827,-0.0694968,-0.0477539,0.0240784,0.0134014,-0.0097871,-0.0136885,0.0262607,-0.0190607,0.0106291,0.0107166,0.0102476,0.0146315,0.0159757,0.0016943,0.0079549,-0.0231221,0.0119135,-0.0196238,0.0164194,-0.0465574,-0.0335657,0.0044281,0.0046942,0.0420798,-0.0155814,0.0115468,0.0445137,-0.0068171,-0.0517230,0.0077528,-0.0288674,0.0520861,0.0108698,0.0307082,-0.3377637,-0.0109314,0.0315015,-0.0643117,0.0176822,0.0087863,0.0110602,-0.0121383,0.0313203,-0.0382766,-0.0130381,-0.0525104,-0.0147920,0.0289710,-0.0320177,0.0116275,0.0022952,-0.0538700,0.0259716,-0.0113441,0.0635893,0.0154730,-0.0025004,-0.0170411,0.0344624,0.0044486,0.0026823,0.0284011,0.0470124,-0.0114609,-0.0148241,-0.0202858,0.0418924,-0.0384444,-0.0191120,0.0147796,0.0102955,-0.0394580,-0.0007361,0.0288115,-0.0771421,0.0223649,0.0191385,0.0117931,-0.0213216,-0.0004940,0.0111546,-0.0006391,0.0350158,0.0292621,0.0156098,-0.0130455,0.0359304,0.0415105,0.0468936,-0.0032122,-0.0248503,0.0208432,-0.0268839,-0.0029901,-0.0169120,0.0455312,-0.0129048,0.0377794,0.0023716,0.0419125,0.0009603,-0.0429436,-0.0467570,0.0389181,-0.0209416,0.0149510,-0.0236718,